// Link público de um menu: metadados para mensageiros e acesso ao pedido no aplicativo.
import Menus from '../../assets/menus-core.js';
import Core from '../../assets/app-core.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function onRequest({request,env,params}){
 const [id,mid,...extra]=Array.isArray(params.rota)?params.rota:[],origin=new URL(request.url).origin;
 const headers={'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'"};
 let c,m;
 if(env.DB&&id&&mid&&!extra.length){const row=await env.DB.prepare('SELECT perfil FROM chefs WHERE id = ? AND publicado = 1 AND COALESCE(oculto, 0) = 0').bind(id).first();if(row){c={...JSON.parse(row.perfil),id};if(!Core.faltaPerfil(c).length)m=Menus.active(c.menus).find(m=>m.id===mid)}}
 if(!m)return new Response('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Menu indisponível</title><body><h1>Este menu não está disponível.</h1><p>O prazo terminou ou o chef pausou a divulgação.</p><a href="/#/especiais">Conhecer outros menus</a></body></html>',{status:404,headers});
 const image=/^\/(?:api\/foto\/[a-f\d]{32}|assets\/(?:servicos|apresentacao)\/[a-z0-9-]+\.webp)$/.test(m.photo)?origin+m.photo:'',description=Menus.price(m)+' · '+Menus.quantity(m)+' · '+Menus.modes[m.mode]+' · Por '+c.name;
 return new Response('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(m.title)+' · '+e(c.name)+'</title><meta name="description" content="'+e(description)+'"><meta property="og:type" content="website"><meta property="og:title" content="'+e(m.title)+' · '+e(c.name)+'"><meta property="og:description" content="'+e(description)+'"><meta property="og:image" content="'+e(image)+'"><meta property="og:url" content="'+e(Menus.link(origin,c,m))+'"><meta name="twitter:card" content="summary_large_image"><style>body{margin:0;background:#f6f3eb;color:#303629;font:17px/1.7 Arial,sans-serif}main{max-width:880px;margin:48px auto;padding:0 24px}img{width:100%;max-height:440px;object-fit:cover;border-radius:22px}h1{font:48px/1.1 Georgia,serif}h2{font:30px Georgia,serif}small{color:#754653}a{color:#455238}.button{display:inline-block;padding:16px 24px;background:#455238;color:#fffdf8;border-radius:12px;text-decoration:none}.items{white-space:pre-line}footer{border-top:1px solid #dedfd2;margin-top:40px;padding:24px 0}.price{font-size:26px;font-weight:bold}</style></head><body><main><small>'+e(m.occasion)+' · '+e(Menus.modes[m.mode])+'</small><h1>'+e(m.title)+'</h1><p>Por '+e(c.name)+' · '+e(c.cities)+'</p><img src="'+e(image)+'" alt="'+e(m.title)+'"><p>'+e(m.description)+'</p><p class="price">'+e(Menus.price(m))+'</p><p>'+e(Menus.quantity(m))+'</p><h2>O cardápio</h2><p class="items">'+e(m.items)+'</p><h2>O que está incluso</h2><p class="items">'+e(m.includes)+'</p><p>Encomendas até '+e(m.deadline.split('-').reverse().join('/'))+'. Valores e disponibilidade sujeitos à confirmação pelo chef.</p><a class="button" href="/#/menu/'+encodeURIComponent(id)+'/'+encodeURIComponent(mid)+'">Pedir orçamento deste menu →</a><footer><a href="/">Seu Chef em Casa</a> · Encontros em torno da boa comida.</footer></main></body></html>',{headers});
}
